INSERT INTO "skill_generated" VALUES('obra','superpowers','brainstorming','faq','1b0710979c671689718d16643abfd0d9b67f74a7','{"items":[{"question":"do I need to brainstorm before I start coding","answer":"Yes, brainstorming must be used before any creative work including creating features, building components, or adding functionality. It has a hard gate that blocks code writing until the design is approved."},{"question":"does brainstorming write code","answer":"No, brainstorming only creates designs and specs; it blocks any code writing or implementation until the design is user-approved."},{"question":"what does the brainstorming skill output","answer":"Brainstorming outputs a design document saved to `docs/superpowers/specs/YYYY-MM-DD-<topic>-design.md` after self-review and user approval."},{"question":"can I use brainstorming with existing projects","answer":"Yes, brainstorming explores current project structure and follows existing patterns. It includes targeted improvements for code that affects the work."},{"question":"can I create visual mockups with brainstorming","answer":"Brainstorming offers an optional Visual Companion browser tool for showing mockups, diagrams, and visual options during design."},{"question":"how many design approaches does brainstorming propose","answer":"Brainstorming proposes 2-3 different approaches with trade-offs and a recommendation before settling on the final design."}],"model":"claude-haiku-4-5-20251001"}','2026-04-24T04:49:27.250Z');
