INSERT INTO "skill_generated" VALUES('vercel-labs','skills','find-skills','faq','5aafd1a88bb4dcd63a0e3bb361f80ff1e376379a','{"items":[{"question":"How do I search for agent skills?","answer":"Use the Skills CLI with `npx skills find [query]` to search interactively or by keyword. You can also browse all available skills at https://skills.sh/ and check the leaderboard for the most popular options."},{"question":"What''s the easiest way to discover new agent skills?","answer":"Start by checking the skills leaderboard at skills.sh to see the most popular and battle-tested skills by install count. If you don''t find what you need there, use `npx skills find [query]` to search by domain or task."},{"question":"How do I install an agent skill?","answer":"Use the command `npx skills add <owner/repo@skill>` to install a skill. You can use the `-g` flag to install globally and `-y` to skip confirmation prompts."},{"question":"How do I know if an agent skill is trustworthy?","answer":"Look for skills with 1,000+ installs, official sources like vercel-labs or anthropics, and check the source repository for GitHub stars (100+ stars is a good indicator). Be cautious with skills under 100 installs or from unknown authors."},{"question":"Can I create my own agent skills?","answer":"Yes, you can create custom agent skills using `npx skills init my-skill-name`. This is useful if you have a specialized task or workflow you want to automate."},{"question":"What should I do if no existing skill solves my problem?","answer":"You can still get help directly using general agent capabilities. If it''s a task you do frequently, you can create your own skill with `npx skills init`."}],"model":"claude-haiku-4-5-20251001"}','2026-04-24T05:52:37.811Z');
INSERT INTO "skill_generated" VALUES('sleekdotdesign','agent-skills','sleek-design-mobile-apps','faq','665b15fba7b04b796c1d28afad40904f4297f0c4','{"items":[{"question":"Does Sleek Design require an API key?","answer":"Yes, you need to create an API key at https://sleek.design/dashboard/api-keys and store it in the SLEEK_API_KEY environment variable. You must have a Pro or higher plan to access the API."},{"question":"Can I export and implement designs created with Sleek?","answer":"Yes, Sleek returns complete HTML code for each screen that you can save directly to a .html file or implement in native frameworks like React Native or SwiftUI by referencing both the HTML structure and rendered screenshots."},{"question":"What image formats does Sleek support for screenshots?","answer":"Sleek supports PNG and WebP formats for screenshots, with configurable scale (1-3), padding, background color, and optional grid overlay."},{"question":"Can I edit specific screens in a Sleek project?","answer":"Yes, you can target specific screens for editing by using the screenId in chat messages via the target.screenId parameter, or let Sleek''s AI decide what screens to create from your full description."},{"question":"What security should I know about using Sleek''s API?","answer":"All requests go exclusively to https://sleek.design over HTTPS, the API key is only transmitted in the Authorization header, and you can create keys with minimal scopes limited to what your task needs."},{"question":"Can I run multiple design requests in parallel?","answer":"Yes, you can run chat requests on different projects concurrently using async polling, but only one active run is allowed per project at a time."}],"model":"claude-haiku-4-5-20251001"}','2026-04-24T05:52:54.297Z');
INSERT INTO "skill_generated" VALUES('roin-orca','skills','simple','faq','d9ef78e64d94021fbf7cb173df0b1e83ede06354','{"items":[{"question":"When should I use the simple brainstorming skill?","answer":"Use it before creative or architectural work like feature design, component creation, or behavioral changes. It''s a lightweight process designed to move quickly from idea to actionable direction without unnecessary overhead."},{"question":"How many design approaches does the brainstorming process propose?","answer":"The process presents 2 approaches with trade-offs, leading with a recommendation and explanation. If rejected, it revises and reproposed up to 2 rounds maximum before asking for direct clarification."},{"question":"Can I use this brainstorming skill for small tasks?","answer":"Yes. The skill scales its process depth to match task complexity; a small bug fix or config change might go through discovery and proposal in a single message, while larger subsystems get more thorough exploration."},{"question":"Do I need to write code during the brainstorming phase?","answer":"No. The skill explicitly does not write code, scaffold files, or take implementation actions until you approve a direction. This ensures focused thinking before building."},{"question":"What happens if I disagree with the proposed direction?","answer":"If you reject a proposal, the skill revises and reproposses up to 2 rounds. If still not aligned after that, it asks you to state what you want directly to find agreement faster."},{"question":"What makes this brainstorming approach different?","answer":"It prioritizes speed and action over ceremony, eliminates process overhead, focuses on what''s needed now (YAGNI), and asks clarifying questions in batches rather than one at a time to keep momentum."}],"model":"claude-haiku-4-5-20251001"}','2026-04-24T05:53:16.257Z');
INSERT INTO "skill_generated" VALUES('nextlevelbuilder','ui-ux-pro-max-skill','ui-ux-pro-max','faq','598db411617cc9257e2aac5166f091d92f5bcc96','{"items":[{"question":"What technology stacks does ui-ux-pro-max support?","answer":"ui-ux-pro-max covers 10 technology stacks including React, Next.js, Vue, Svelte, SwiftUI, React Native, Flutter, Tailwind, shadcn/ui, and HTML/CSS."},{"question":"Does ui-ux-pro-max support shadcn/ui?","answer":"Yes, shadcn/ui is one of the 10 supported technology stacks, and the skill includes integration with the shadcn/ui MCP for component search and examples."},{"question":"What design styles are included in ui-ux-pro-max?","answer":"The skill includes 50+ styles such as glassmorphism, claymorphism, minimalism, brutalism, neumorphism, bento grid, dark mode, responsive, skeuomorphism, and flat design."},{"question":"Can ui-ux-pro-max help with web accessibility?","answer":"Yes, ui-ux-pro-max includes 99 UX guidelines covering accessibility and interaction patterns as part of its comprehensive design intelligence."},{"question":"Does ui-ux-pro-max work for mobile app design?","answer":"Yes, it supports mobile development with SwiftUI, React Native, and Flutter, and includes guidance for mobile app projects alongside web and dashboard designs."},{"question":"How many color palettes does ui-ux-pro-max include?","answer":"ui-ux-pro-max includes 161 color palettes to choose from for your designs."}],"model":"claude-haiku-4-5-20251001"}','2026-04-24T05:53:59.461Z');
INSERT INTO "skill_generated" VALUES('browser-use','browser-use','browser-use','faq','3f17825359f1fc681fde9506d58ec3cdcceb1629','{"items":[{"question":"does browser-use require Chrome to be installed","answer":"No, browser-use uses headless Chromium by default with no setup required. You can optionally connect to your real Chrome using `browser-use connect` to preserve logins and cookies."},{"question":"how fast is browser-use","answer":"browser-use provides approximately 50ms latency per command through a persistent background daemon that keeps the browser open between calls."},{"question":"how do I fill forms and automate user interactions with browser-use","answer":"Use commands like `browser-use input <index> \"text\"` to fill fields, `browser-use select` for dropdowns, `browser-use click` to interact with elements, and `browser-use upload` for file uploads."},{"question":"can I use browser-use to extract data from websites","answer":"Yes, browser-use includes extraction commands like `get html`, `get text`, `get value`, and `eval` for executing JavaScript; you can also use `browser-use screenshot` to capture page content."},{"question":"does browser-use support cloud browsers","answer":"Yes, browser-use supports cloud browsers via `browser-use cloud connect`, which provisions a zero-config cloud browser with a persistent profile."},{"question":"what do I do if browser-use connect fails","answer":"If `browser-use connect` cannot find your Chrome, either enable remote debugging in Chrome and retry, or run `browser-use --profile \"ProfileName\" open <url>` to launch Chromium with one of your Chrome profiles."}],"model":"claude-haiku-4-5-20251001"}','2026-04-24T05:54:24.643Z');
INSERT INTO "skill_generated" VALUES('coreyhaines31','marketingskills','seo-audit','faq','cce9c2038ed4f24a014fbeaa0b20287a4d3eae14','{"items":[{"question":"Can this audit multilingual and international sites?","answer":"Yes, it includes detailed assessment of hreflang tags, canonicalization across locales, international sitemap structure, and content quality across language variants. It checks for common mistakes like missing self-referencing hreflang entries, invalid language codes, and cross-locale canonical conflicts that suppress indexing."},{"question":"Does it check for schema markup and structured data?","answer":"It can validate schema markup using browser tools and Google''s Rich Results Test, which render JavaScript. However, it notes that static fetching tools cannot detect schema injected by CMS plugins (AIOSEO, Yoast, RankMath), so browser-based validation is required for accurate detection."},{"question":"What Core Web Vitals does it measure?","answer":"It audits Largest Contentful Paint (LCP < 2.5s), Interaction to Next Paint (INP < 200ms), and Cumulative Layout Shift (CLS < 0.1). It includes assessment of server response time, image optimization, JavaScript execution, and caching strategies that impact these metrics."},{"question":"Does it work for SaaS, e-commerce, and blog sites?","answer":"Yes, it includes site-type-specific audit sections covering common issues like thin product pages in SaaS, duplicate content in e-commerce category pages, and keyword cannibalization in blogs. It also covers local business and multilingual site patterns."},{"question":"What does it check for indexation issues?","answer":"It audits noindex tags on important pages, canonical tag direction, redirect chains, soft 404 errors, duplicate content without proper canonicals, and generates a prioritized action plan based on crawlability, indexation status, and Core Web Vitals."}],"model":"claude-haiku-4-5-20251001"}','2026-04-24T05:54:44.005Z');
INSERT INTO "skill_generated" VALUES('squirrelscan','skills','audit-website','faq','22fe62e5294144f629adda67ebd0508271705f2e','{"items":[{"question":"What website issues can the audit-website skill detect?","answer":"It checks for 230+ issues across 21 categories including broken links, meta tags, structured data, heading hierarchy, image alt text, security headers, HTTPS usage, mobile-friendliness, accessibility problems, and performance bottlenecks. The skill analyzes SEO, technical, content, performance, security, and legal compliance across your entire website."},{"question":"Do I need to install anything to use audit-website?","answer":"Yes, the squirrel CLI must be installed and accessible in your PATH. You can download it from squirrelscan.com/download and verify installation by running `squirrel --version`."},{"question":"What''s the difference between quick, surface, and full coverage modes?","answer":"Quick mode scans 25 pages for fast health checks, surface mode (default) scans 100 pages with smart pattern sampling, and full mode scans up to 500 pages for comprehensive analysis. Surface mode is efficient for sites with many similar pages since it only crawls one sample per URL pattern."},{"question":"Can I audit live websites or only local projects?","answer":"You can audit both live websites and local projects. The skill recommends auditing live websites first since they provide a true representation of performance and rendering issues that might not appear locally."},{"question":"What output formats does audit-website support?","answer":"It supports console (default), text, json, html, markdown, and llm formats. The llm format is recommended as it provides a compact, exhaustive output optimized for AI analysis."},{"question":"Can I compare audit results over time or against a baseline?","answer":"Yes, you can use diff mode with `squirrel report --diff <audit-id>` to compare against a specific baseline audit, or `--regression-since example.com` to compare against a baseline domain and detect regressions."}],"model":"claude-haiku-4-5-20251001"}','2026-04-24T05:55:04.450Z');
INSERT INTO "skill_generated" VALUES('coreyhaines31','marketingskills','copywriting','faq','4363f01a7de8ed2ae417b5afedccef69f1d18b3a','{"items":[{"question":"What types of pages can the copywriting skill help with?","answer":"The copywriting skill covers marketing copy for homepages, landing pages, pricing pages, feature pages, and about pages. For email campaigns, see the email-sequence skill instead."},{"question":"What context should I gather before using the copywriting skill?","answer":"You should gather information about page purpose and primary action, your target audience and their pain points, your product or offer and what makes it different, and where your traffic is coming from. The skill includes a structured checklist to gather this context before writing."},{"question":"What are the main principles for writing good marketing copy?","answer":"The copywriting skill emphasizes clarity over cleverness, benefits over features, specificity over vagueness, customer language over company language, and active voice over passive. It also recommends being direct, using rhetorical questions, and showing the outcome rather than just telling."},{"question":"Does copywriting include page structure templates?","answer":"Yes, the skill includes a page structure framework with sections for headlines, subheadlines, social proof, problem/pain, solution/benefits, how it works, and objection handling. It also references copy-frameworks.md for detailed templates and formulas."},{"question":"What''s the difference between copywriting and copy-editing?","answer":"Copywriting is for creating the initial marketing copy draft, while copy-editing is a separate skill for polishing and refining existing copy line-by-line. The skill recommends using copy-editing after you''ve completed your copywriting draft."},{"question":"Does copywriting include CTA (call-to-action) guidance?","answer":"Yes, the skill provides CTA copy guidelines with formulas like [Action Verb] + [What They Get] + [Qualifier]. It recommends specific CTAs like ''Start Free Trial'' over weak alternatives like ''Click Here'' or ''Learn More''."}],"model":"claude-haiku-4-5-20251001"}','2026-04-24T05:55:24.469Z');
INSERT INTO "skill_generated" VALUES('anthropics','claude-plugins-official','frontend-design','faq','bb9cd6e564c2d849a4fafbcc52f2440337b1c7bf','{"items":[{"question":"How does frontend-design help avoid generic AI-generated aesthetics?","answer":"Frontend-design emphasizes committing to a bold, intentional aesthetic direction before coding, then executing with precision. It explicitly warns against generic choices like overused fonts (Inter, Roboto, Arial), cliched color schemes, and predictable layouts, instead pushing toward distinctive, context-specific designs that feel genuinely crafted."},{"question":"What frameworks and languages does frontend-design support?","answer":"Frontend-design works with HTML/CSS/JS, React, Vue, and other frontend frameworks. It provides framework-agnostic design principles while offering library-specific guidance, such as using the Motion library for React animations."},{"question":"Can I use frontend-design to create minimalist interfaces?","answer":"Yes. Frontend-design supports both bold maximalism and refined minimalism as valid aesthetic directions. The key is intentionality and precision; minimalist designs require careful attention to spacing, typography, and subtle details to achieve elegance."},{"question":"Does frontend-design include guidance on typography and fonts?","answer":"Yes. Frontend-design recommends choosing distinctive, characterful fonts that elevate aesthetics and avoid generic options. It advises pairing a distinctive display font with a refined body font, treating typography as a core element of aesthetic direction."},{"question":"How does frontend-design approach motion and animations?","answer":"Frontend-design prioritizes high-impact moments like staggered page-load reveals over scattered micro-interactions, favors CSS-only solutions for HTML, and recommends using scroll-triggering and hover states to surprise and delight users."},{"question":"What is the design thinking process in frontend-design?","answer":"Frontend-design recommends first understanding the purpose, audience, and tone before coding, then committing to a clear conceptual direction (such as brutalist, organic, luxury, or playful) and executing it with intentionality and precision."}],"model":"claude-haiku-4-5-20251001"}','2026-04-24T05:56:10.846Z');
INSERT INTO "skill_generated" VALUES('anthropics','claude-plugins-official','frontend-design','tags','bb9cd6e564c2d849a4fafbcc52f2440337b1c7bf','{"tags":["frontend","design"],"model":"claude-haiku-4-5-20251001"}','2026-04-24T05:56:33.492Z');
